 1→import { z } from "zod";
 2→import { createEventSchema, updateEventSchema } from "@/domain/validation";
 3→import { adminProcedure, publicProcedure, router } from "../context";
 4→
 5→/**
 6→ * イベント操作ルーター
 7→
 8→ * ctx.eventService: コンテキストからService層を取得
 9→ * input: フロントエンドから送られてくるデータ（Zodでバリデーション済み）
10→ */
11→export const eventsRouter = router({
12→  list: publicProcedure.query(async ({ ctx }) => {
13→    return await ctx.eventService.getAllEvents();
14→  }),
15→  listPickup: publicProcedure.query(async ({ ctx }) => {
16→    return await ctx.eventService.getPickupEvents();
17→  }),
18→  listByMonth: publicProcedure
19→    .input(
20→      z.object({
21→        year: z.number(),
22→        month: z.number(),
23→      }),
24→    )
25→    .query(async ({ ctx, input }) => {
26→      return await ctx.eventService.getEventsByMonth(input.year, input.month);
27→    }),
28→  getById: publicProcedure
29→    .input(z.string()) // 入力は文字列（ID）
30→    .query(async ({ ctx, input }) => {
31→      return await ctx.eventService.getEventById(input);
32→    }),
33→  create: adminProcedure
34→    .input(createEventSchema)
35→    .mutation(async ({ ctx, input }) => {
36→      return await ctx.eventService.createEvent(input);
37→    }),
38→  update: adminProcedure
39→    .input(
40→      z.object({
41→        id: z.string(),
42→        data: updateEventSchema,
43→      }),
44→    )
45→    .mutation(async ({ ctx, input }) => {
46→      return await ctx.eventService.updateEvent(input.id, input.data);
47→    }),
48→  delete: adminProcedure.input(z.string()).mutation(async ({ ctx, input }) => {
49→    return await ctx.eventService.deleteEvent(input);
50→  }),
51→  /**
52→   * イベントを公開する
53→   */
54→  publish: adminProcedure.input(z.string()).mutation(async ({ ctx, input }) => {
55→    return await ctx.eventService.publishEvent(input);
56→  }),
57→  /**
58→   * イベントを非公開にする
59→   */
60→  unpublish: adminProcedure
61→    .input(z.string())
62→    .mutation(async ({ ctx, input }) => {
63→      return await ctx.eventService.unpublishEvent(input);
64→    }),
65→});
