 44→ */
 45→function cleanFormData(data: UpdateEventFormData): UpdateEventFormData {
 46→  return {
 47→    ...data,
 48→    pricing: data.pricing?.length ? data.pricing : null,
 49→    performers: data.performers?.length ? data.performers : null,
 50→    hashtags: data.hashtags?.length ? data.hashtags : null,
 51→  };
