 54→/**
 55→ * イベント編集フォーム
 56→ *
 57→ * useFormで自動的にデータを取得し、フォームを管理
 58→ * URLから自動的にIDを取得するため、propsは不要
 59→ */
 60→export function EventEditForm() {
 61→  const params = useParams();
 62→  const eventId = params.id as string;
 63→  const { isFileUploading, uploadIfNeeded } = useImageUpload();
 64→
 65→  const {
 66→    refineCore: { onFinish, query },
 67→    handleSubmit,
 68→    control,
 69→    setError,
 70→  } = useForm<EventEntity, HttpError, UpdateEventFormData>({
 71→    resolver: zodResolver(updateEventFormSchema),
 72→    refineCoreProps: {
 73→      resource: "events",
 74→      id: eventId,
 75→      action: "edit",
 76→      redirect: "show",
 77→    },
 78→    // NOTE: uncontrolled→controlled切替を防ぐための初期値。
 79→    // Refineのedit用useFormはAPI取得後にreset()で上書きするため、
 80→    // ここのdefaultValuesはあくまでプレースホルダー。
 81→    // 実際のサーバーデータは各フィールドのdefaultValue propで明示的に渡している。
 82→    // cf. https://react.dev/reference/react-dom/components/input#controlling-an-input-with-a-state-variable
 83→    defaultValues: {
 84→      title: "",
 85→      description: "",
 86→      date: "",
 87→      type: undefined,
 88→      thumbnail: undefined,
 89→      isPickup: false,
 90→      openTime: DEFAULT_OPEN_TIME,
 91→      startTime: DEFAULT_START_TIME,
 92→      pricing: [],
 93→      performers: [],
 94→      hashtags: [],
 95→    },
 96→  });
 97→
 98→  const { data, isLoading, isError, refetch } = query ?? {};
 99→  const defaultValues = data?.data;
100→
101→  if (isLoading) return <EventLoading viewType="edit" />;
102→  if (isError) return <EventError viewType="edit" onRetry={refetch} />;
103→  if (!defaultValues) return <EventNotFound viewType="edit" />;
104→
105→  const onSubmit = async (formData: UpdateEventFormData) => {
106→    try {
107→      const cleaned = cleanFormData(formData);
108→      const submitData = await uploadIfNeeded<UpdateEventFormData>(
109→        cleaned,
110→        setError,
111→      );
112→      if (!submitData) return; // アップロード失敗
113→
114→      await onFinish(submitData);
115→    } catch (error) {
116→      console.error("Form submission error:", error);
117→    }
118→  };
119→
120→  return (
121→    <EditView>
122→      <EditViewHeader />
123→      <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
124→        <Card>
125→          <CardHeader>
126→            <CardTitle>イベント基本情報</CardTitle>
127→          </CardHeader>
128→          <CardContent className="space-y-4">
129→            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
130→              <div className="space-y-4">
131→                <EventTitleField
132→                  control={control}
133→                  defaultValue={defaultValues.title}
134→                />
135→                <EventDateField
136→                  control={control}
137→                  defaultValue={defaultValues.date}
138→                />
139→                <EventTimeFields
140→                  control={control}
141→                  defaultOpenTime={defaultValues.openTime}
142→                  defaultStartTime={defaultValues.startTime}
143→                />
144→                <EventTypeField
145→                  control={control}
146→                  defaultValue={defaultValues.type}
147→                />
148→                <EventPublicationStatusField
149→                  control={control}
150→                  defaultValue={defaultValues.publicationStatus}
151→                />
152→                <EventIsPickupField
153→                  control={control}
154→                  defaultValue={defaultValues.isPickup}
155→                />
156→              </div>
157→              <div>
158→                <EventThumbnailField
159→                  control={control}
160→                  defaultValue={defaultValues.thumbnail}
161→                />
162→              </div>
163→            </div>
164→          </CardContent>
165→        </Card>
166→
167→        <Card>
168→          <CardHeader>
169→            <CardTitle>イベント詳細</CardTitle>
170→          </CardHeader>
171→          <CardContent className="space-y-6">
172→            <EventDescriptionField
173→              control={control}
174→              defaultValue={defaultValues.description}
175→            />
176→            <EventPricingField
177→              control={control}
178→              defaultValue={defaultValues.pricing}
179→            />
180→            <EventPerformersField
181→              control={control}
182→              defaultValue={defaultValues.performers}
183→            />
184→            <EventHashtagsField
185→              control={control}
186→              defaultValue={defaultValues.hashtags}
187→            />
188→          </CardContent>
189→        </Card>
190→
191→        <div className="flex justify-end gap-2">
192→          <Button type="submit" disabled={isFileUploading}>
193→            {isFileUploading ? "画像をアップロード中..." : "更新"}
194→          </Button>
195→        </div>
196→      </form>
197→    </EditView>
198→  );
