 4→import { PageTitle } from "@/components/PageTitle";
 5→import { createPublicServerCaller } from "@/infrastructure/trpc/server";
 6→import { cn } from "@/utils/cn";
 7→import { APP_TIMEZONE } from "@/utils/date";
 8→import { EventList } from "./_components/EventList";
 9→import { EventsContentSkeleton } from "./_components/EventsContentSkeleton";
10→import { MonthNavigation } from "./_components/MonthNavigation";
11→import { ScheduleAnnouncement } from "./_components/ScheduleAnnouncement";
12→
13→export const metadata: Metadata = {
14→  title: "イベント",
15→  description:
16→    "SOY-POYで開催されるイベント一覧。オープンマイク、コンサート、ワークショップなど。",
17→};
18→
19→export const revalidate = 300;
20→
21→interface EventsPageProps {
22→  searchParams: Promise<{ month: string }>;
23→}
24→
25→//TODO: queryパラメータの設計する。
26→// defaultは今月 yearも分けた方がよさそう。
27→export default async function EventsPage({ searchParams }: EventsPageProps) {
28→  const resolvedSearchParams = await searchParams;
29→  const { year, month } = getYearAndMonthFromSearchParams(
30→    resolvedSearchParams.month,
31→  );
32→
33→  return (
34→    <div className={cn("container mx-auto max-w-5xl", "px-12 md:px-16 py-8")}>
35→      <PageTitle title="EVENTS" subtitle="Monthly Lineup" />
36→      <MonthNavigation year={year} month={month} />
37→      <Suspense fallback={<EventsContentSkeleton />}>
38→        <EventsContent year={year} month={month} />
39→      </Suspense>
40→    </div>
41→  );
42→}
43→
44→async function EventsContent({ year, month }: { year: number; month: number }) {
45→  const trpc = await createPublicServerCaller();
46→  const [events, closedDays] = await Promise.all([
47→    trpc.events.listByMonth({ year, month }),
48→    trpc.closedDays.listByMonth({ year, month }),
49→  ]);
50→
51→  return (
52→    <>
53→      <EventList events={events} />
54→      <ScheduleAnnouncement
55→        year={year}
56→        month={month}
57→        events={events}
58→        closedDays={closedDays}
59→      />
60→    </>
61→  );
62→}
63→
64→function getYearAndMonthFromSearchParams(monthParam: string | undefined) {
65→  if (!monthParam) {
66→    const now = DateTime.now().setZone(APP_TIMEZONE);
67→    return { year: now.year, month: now.month };
68→  }
69→  const [yearStr, monthStr] = monthParam.split("-");
70→  return {
71→    year: Number.parseInt(yearStr, 10),
72→    month: Number.parseInt(monthStr, 10),
73→  };
74→}
