  3→import { ImageIcon, Upload, X } from "lucide-react";
  4→import Image from "next/image";
  5→import { CldImage } from "next-cloudinary";
  6→import { useEffect, useRef, useState } from "react";
  7→
  8→import { Button } from "@/components/shadcn/button";
  9→import { Input } from "@/components/shadcn/input";
 10→import { cn } from "@/utils/cn";
 11→import { compressImage, type ImageCompressionOptions } from "./compression";
 12→
 13→import type { ImageChangeHandler, ImageValue } from "./type";
 14→
 15→export interface ImageUploaderProps {
 16→  /**
 17→   * 現在の値（File or URLstring）
 18→   */
 19→  value?: ImageValue;
 20→
 21→  /**
 22→   * 値変更時のコールバック
 23→   */
 24→  onChange?: ImageChangeHandler;
 25→
 26→  /**
 27→   * 追加のクラス名
 28→   */
 29→  className?: string;
 30→
 31→  /**
 32→   * アスペクト比（デフォルト: 5:4）
 33→   */
 34→  aspectRatio?: string;
 35→
 36→  /**
 37→   * 許可するファイル形式（デフォルト: png, jpeg, svg）
 38→   */
 39→  acceptedFileTypes?: string;
 40→
 41→  /**
 42→   * 画像圧縮オプション
 43→   */
 44→  compressionOptions?: ImageCompressionOptions;
 45→}
 46→
 47→/**
 48→ * v0で生成したコードをベースに、react-hook-formとの互換性を保つように修正したコード
 49→ * previewやデータのやりとりについては、自前での実装
 50→ * 画像圧縮機能を追加
 51→ */
 52→export function ImageUploader({
 53→  value,
 54→  onChange,
 55→  className,
 56→  aspectRatio = "aspect-insta",
 57→  acceptedFileTypes = "image/png,image/jpeg",
 58→  compressionOptions,
 59→}: ImageUploaderProps) {
 60→  const fileInputRef = useRef<HTMLInputElement>(null);
 61→  const [preview, setPreview] = useState<string | undefined>(undefined);
 62→  const [isCompressing, setIsCompressing] = useState(false);
 63→
 64→  // 値が変更された時の処理
 65→  useEffect(() => {
 66→    // null または undefined の場合はプレビューをクリア
 67→    if (value === null || value === undefined) {
 68→      setPreview(undefined);
 69→      return;
 70→    }
 71→
 72→    // URLstring の場合
 73→    if (typeof value === "string") {
 74→      setPreview(value);
 75→      return;
 76→    }
 77→
 78→    // Fileオブジェクトの処理
 79→    if (value instanceof File) {
 80→      const reader = new FileReader();
 81→      reader.onload = (e) => {
 82→        const result = e.target?.result as string;
 83→        setPreview(result);
 84→      };
 85→      reader.readAsDataURL(value);
 86→    }
 87→  }, [value]);
 88→
 89→  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
 90→    const file = e.target.files?.[0];
 91→    if (!file) return;
 92→
 93→    setIsCompressing(true);
 94→
 95→    try {
 96→      // 画像圧縮を実行
 97→      const compressedFile = await compressImage({
 98→        file,
 99→        ...(compressionOptions && { options: compressionOptions }),
100→      });
101→
102→      onChange?.(compressedFile);
103→    } finally {
104→      setIsCompressing(false);
105→    }
106→  };
107→
108→  const handleRemove = (e: React.MouseEvent) => {
109→    e.stopPropagation();
110→    onChange?.(null); // react-hook-formとの互換性のためnullを使用
111→    if (fileInputRef.current) {
112→      fileInputRef.current.value = "";
113→    }
114→  };
115→
116→  const openFileDialog = () => {
117→    if (isCompressing) return;
118→    fileInputRef.current?.click();
119→  };
120→
121→  // Cloudinary URLかどうかを判定
122→  const _isCloudinaryUrl = (url: string): boolean => {
123→    return (
124→      url.includes("res.cloudinary.com") ||
125→      (!url.startsWith("http") && url.includes("/"))
126→    );
127→  };
128→
129→  return (
130→    <div className={cn("relative", aspectRatio, className)}>
131→      <button
132→        type="button"
133→        className={cn(
134→          "w-full h-full border-2 border-dashed border-muted-foreground/25 rounded-lg overflow-hidden",
135→          "transition-colors hover:border-muted-foreground/50",
136→          isCompressing ? "opacity-50 cursor-not-allowed" : "cursor-pointer",
137→        )}
138→        onClick={openFileDialog}
139→        aria-label={preview ? "画像を変更" : "画像をアップロード"}
140→        title={preview ? "画像を変更" : "画像をアップロード"}
141→        disabled={isCompressing}
142→        aria-busy={isCompressing}
143→      >
144→        {preview ? (
145→          <div className="relative w-full h-full">
146→            {typeof preview === "string" && _isCloudinaryUrl(preview) ? (
147→              <CldImage
148→                src={preview}
149→                alt="アップロードされた画像のプレビュー"
150→                fill
151→                crop="fill"
152→                gravity="auto"
153→                className="object-cover"
154→                sizes="(max-width: 768px) 100vw, 50vw"
155→              />
156→            ) : (
157→              <Image
158→                src={preview}
159→                alt="アップロードされた画像のプレビュー"
160→                fill
161→                className="object-cover"
162→                sizes="(max-width: 768px) 100vw, 50vw"
163→              />
164→            )}
165→
166→            {/* オーバーレイ */}
167→            <div className="absolute inset-0 bg-black/0 hover:bg-black/20 transition-colors flex items-center justify-center">
168→              <div className="opacity-0 hover:opacity-100 transition-opacity">
169→                <Upload
170→                  className="h-8 w-8 text-white drop-shadow-lg"
171→                  aria-hidden="true"
172→                />
173→              </div>
174→            </div>
175→          </div>
176→        ) : (
177→          <ImageUploaderPlaceholder />
178→        )}
179→      </button>
180→
181→      {/* 削除ボタン */}
182→      {preview && !isCompressing && (
183→        <Button
184→          type="button"
185→          variant="secondary"
186→          size="icon"
187→          className="absolute top-2 right-2 h-8 w-8 rounded-full shadow-lg z-10"
188→          onClick={handleRemove}
189→          aria-label="画像を削除"
190→          title="画像を削除"
191→        >
192→          <X className="h-4 w-4" aria-hidden="true" />
193→        </Button>
194→      )}
195→
196→      <Input
197→        ref={fileInputRef}
198→        type="file"
199→        className="sr-only"
200→        accept={acceptedFileTypes}
201→        onChange={(e) => {
202→          void handleFileSelect(e);
203→        }}
204→        disabled={isCompressing}
205→        aria-label="画像ファイルを選択"
206→      />
207→    </div>
208→  );
209→}
210→
211→function ImageUploaderPlaceholder() {
212→  return (
213→    <div className="flex flex-col items-center justify-center h-full p-6 text-center">
214→      <ImageIcon
215→        className="h-12 w-12 text-muted-foreground mb-4"
216→        aria-hidden="true"
217→      />
218→      <p className="text-sm font-medium text-muted-foreground mb-1">
219→        クリックして画像をアップロード
220→      </p>
221→      <p className="text-xs text-muted-foreground">PNG, JPEG (最大 5MB)</p>
222→    </div>
223→  );
224→}
