 1→import { nanoid } from "nanoid";
 2→import { PICKUP_EVENTS_LIMIT } from "@/constant/pickupEvents";
 3→import { type EventEntity, PublicationStatus } from "@/domain/entities";
 4→import type { EventRepository } from "@/domain/repositories/eventRepository";
 5→
 6→/**
 7→ * イベントサービス
 8→ * ビジネスロジックを担当
 9→ *
10→ * 注意: このサービス層は画像アップロードを行いません。
11→ * 画像は事前にクライアント→Server Action (uploadImageAction) でアップロードされ、
12→ * URLに変換された状態でこのサービスに渡されることを前提とします。
13→ * tRPCでFileをJSONシリアライズに失敗するため
14→ * TODO: transformer: superjson,をtRPCで設定することで解決するか試す。
15→ */
16→export class EventService {
17→  constructor(private repository: EventRepository) {}
18→  async getAllEvents(): Promise<EventEntity[]> {
19→    return await this.repository.list();
20→  }
21→  async getEventById(id: string): Promise<EventEntity | undefined> {
22→    return await this.repository.findById(id);
23→  }
24→  async createEvent(
25→    input: Omit<EventEntity, "id" | "publicationStatus">,
26→  ): Promise<EventEntity> {
27→    return await this.repository.create({
28→      id: nanoid(),
29→      publicationStatus: PublicationStatus.Draft,
30→      ...input,
31→    });
32→  }
33→  async updateEvent(
34→    id: string,
35→    input: Partial<Omit<EventEntity, "id">>,
36→  ): Promise<EventEntity> {
37→    return await this.repository.update(id, input);
38→  }
39→  async deleteEvent(id: string): Promise<EventEntity> {
40→    return await this.repository.update(id, {
41→      publicationStatus: PublicationStatus.Archived,
42→    });
43→  }
44→  async getEventsByMonth(year: number, month: number): Promise<EventEntity[]> {
45→    return await this.repository.listByMonth(year, month);
46→  }
47→  async getPickupEvents(): Promise<EventEntity[]> {
48→    const pickupEvents = await this.repository.listPickup();
49→    if (pickupEvents.length >= PICKUP_EVENTS_LIMIT) {
50→      return pickupEvents;
51→    }
52→    const remaining = PICKUP_EVENTS_LIMIT - pickupEvents.length;
53→    const excludeIds = pickupEvents.map((e) => e.id);
54→    const fallbackEvents = await this.repository.listLatestPublished(
55→      remaining,
56→      excludeIds,
57→    );
58→    return [...pickupEvents, ...fallbackEvents];
59→  }
60→  async publishEvent(id: string): Promise<EventEntity> {
61→    const event = await this.repository.findById(id);
62→    if (!event) throw new Error("イベントが見つかりません");
63→    if (event.publicationStatus !== PublicationStatus.Draft) {
64→      throw new Error("下書きのみ公開できます");
65→    }
66→    return await this.repository.update(id, {
67→      publicationStatus: PublicationStatus.Published,
68→    });
69→  }
70→  async unpublishEvent(id: string): Promise<EventEntity> {
71→    const event = await this.repository.findById(id);
72→    if (!event) throw new Error("イベントが見つかりません");
73→    if (event.publicationStatus !== PublicationStatus.Published) {
74→      throw new Error("公開中イベントのみ下書きに戻せます");
75→    }
76→    return await this.repository.update(id, {
77→      publicationStatus: PublicationStatus.Draft,
78→    });
79→  }
80→}
