  1→import { and, desc, eq, notInArray, sql } from "drizzle-orm";
  2→import { PICKUP_EVENTS_LIMIT } from "@/constant/pickupEvents";
  3→import { PublicationStatus } from "@/domain/entities";
  4→import type { EventEntity } from "@/domain/entities/";
  5→import type { Performer } from "@/domain/entities/event/performer";
  6→import type { PricingTier } from "@/domain/entities/event/pricing";
  7→import type { EventRepository } from "@/domain/repositories/eventRepository";
  8→import { db } from "../index";
  9→import type { DrizzleEvent, DrizzleEventInsert } from "../schema";
 10→import { events } from "../schema";
 11→
 12→/**
 13→ * Drizzleを使用したEventRepository実装
 14→ */
 15→export class DrizzleEventRepository implements EventRepository {
 16→  /**
 17→   * 全てのイベントを取得
 18→   */
 19→  async list(): Promise<EventEntity[]> {
 20→    const drizzleEvents = await db
 21→      .select()
 22→      .from(events)
 23→      .orderBy(desc(events.date));
 24→    return drizzleEvents.map(this.toDomainEntity);
 25→  }
 26→
 27→  /**
 28→   * 指定月のイベントを取得
 29→   */
 30→  async listByMonth(year: number, month: number): Promise<EventEntity[]> {
 31→    const drizzleEvents = await db
 32→      .select()
 33→      .from(events)
 34→      .where(
 35→        and(
 36→          eq(events.publicationStatus, PublicationStatus.Published),
 37→          sql`EXTRACT(YEAR FROM ${events.date}) = ${year}`,
 38→          sql`EXTRACT(MONTH FROM ${events.date}) = ${month}`,
 39→        ),
 40→      );
 41→    return drizzleEvents.map(this.toDomainEntity);
 42→  }
 43→
 44→  /**
 45→   * ピックアップイベントを取得
 46→   * isPickup=true、公開済みのみ、日付降順（最新順）、最大4件
 47→   */
 48→  async listPickup(): Promise<EventEntity[]> {
 49→    const drizzleEvents = await db
 50→      .select()
 51→      .from(events)
 52→      .where(
 53→        and(
 54→          eq(events.isPickup, true),
 55→          eq(events.publicationStatus, PublicationStatus.Published),
 56→        ),
 57→      )
 58→      .orderBy(desc(events.date))
 59→      .limit(PICKUP_EVENTS_LIMIT);
 60→    return drizzleEvents.map(this.toDomainEntity);
 61→  }
 62→
 63→  /**
 64→   * 最新の公開済みイベントを取得（日付降順）
 65→   */
 66→  async listLatestPublished(
 67→    limit: number,
 68→    excludeIds: string[] = [],
 69→  ): Promise<EventEntity[]> {
 70→    if (limit <= 0) return [];
 71→    const conditions = [
 72→      eq(events.publicationStatus, PublicationStatus.Published),
 73→    ];
 74→    if (excludeIds.length > 0) {
 75→      conditions.push(notInArray(events.id, excludeIds));
 76→    }
 77→    const drizzleEvents = await db
 78→      .select()
 79→      .from(events)
 80→      .where(and(...conditions))
 81→      .orderBy(desc(events.date))
 82→      .limit(limit);
 83→    return drizzleEvents.map(this.toDomainEntity);
 84→  }
 85→
 86→  /**
 87→   * IDによるイベント取得
 88→   */
 89→  async findById(id: string): Promise<EventEntity | undefined> {
 90→    const [drizzleEvent] = await db
 91→      .select()
 92→      .from(events)
 93→      .where(eq(events.id, id))
 94→      .limit(1);
 95→
 96→    return drizzleEvent ? this.toDomainEntity(drizzleEvent) : undefined;
 97→  }
 98→
 99→  /**
100→   * イベントを作成
101→   */
102→  async create(event: EventEntity): Promise<EventEntity> {
103→    const insertData: DrizzleEventInsert = {
104→      id: event.id,
105→      publicationStatus: event.publicationStatus,
106→      title: event.title,
107→      date: event.date,
108→      description: event.description ?? null,
109→      thumbnail: event.thumbnail ?? null,
110→      type: event.type,
111→      isPickup: event.isPickup,
112→      openTime: event.openTime,
113→      startTime: event.startTime,
114→      pricing: event.pricing ?? null,
115→      performers: event.performers ?? null,
116→      hashtags: event.hashtags ?? null,
117→    };
118→
119→    await db.insert(events).values(insertData);
120→
121→    return event;
122→  }
123→
124→  /**
125→   * イベントを更新
126→   */
127→  async update(
128→    id: string,
129→    event: Partial<Omit<EventEntity, "id">>,
130→  ): Promise<EventEntity> {
131→    const updateData: Partial<DrizzleEventInsert> = {
132→      ...(event.publicationStatus !== undefined && {
133→        publicationStatus: event.publicationStatus,
134→      }),
135→      ...(event.title !== undefined && { title: event.title }),
136→      ...(event.date !== undefined && { date: event.date }),
137→      ...(event.description !== undefined && {
138→        description: event.description ?? null,
139→      }),
140→      ...(event.thumbnail !== undefined && {
141→        thumbnail: event.thumbnail ?? null,
142→      }),
143→      ...(event.type !== undefined && { type: event.type }),
144→      ...(event.isPickup !== undefined && { isPickup: event.isPickup }),
145→      ...(event.openTime !== undefined && {
146→        openTime: event.openTime,
147→      }),
148→      ...(event.startTime !== undefined && {
149→        startTime: event.startTime,
150→      }),
151→      ...(event.pricing !== undefined && {
152→        pricing: event.pricing ?? null,
153→      }),
154→      ...(event.performers !== undefined && {
155→        performers: event.performers ?? null,
156→      }),
157→      ...(event.hashtags !== undefined && {
158→        hashtags: event.hashtags ?? null,
159→      }),
160→    };
161→
162→    const [updated] = await db
163→      .update(events)
164→      .set(updateData)
165→      .where(eq(events.id, id))
166→      .returning();
167→
168→    if (!updated) {
169→      throw new Error(`イベントが見つかりません (id: ${id})`);
170→    }
171→
172→    return this.toDomainEntity(updated);
173→  }
174→
175→  /**
176→   * イベントを削除（論理削除：Archived に変更）
177→   */
178→  async delete(id: string): Promise<void> {
179→    const [deleted] = await db
180→      .update(events)
181→      .set({ publicationStatus: PublicationStatus.Archived })
182→      .where(eq(events.id, id))
183→      .returning();
184→
185→    if (!deleted) {
186→      throw new Error(`イベントが見つかりません (id: ${id})`);
187→    }
188→  }
189→
190→  /**
191→   * Drizzleのイベントデータをドメインエンティティに変換
192→   */
193→  private toDomainEntity(drizzleEvent: DrizzleEvent): EventEntity {
194→    return {
195→      id: drizzleEvent.id,
196→      publicationStatus:
197→        drizzleEvent.publicationStatus as EventEntity["publicationStatus"],
198→      title: drizzleEvent.title,
199→      date: drizzleEvent.date,
200→      description: drizzleEvent.description ?? undefined,
201→      thumbnail: drizzleEvent.thumbnail ?? undefined,
202→      type: drizzleEvent.type as EventEntity["type"],
203→      isPickup: drizzleEvent.isPickup,
204→      openTime: drizzleEvent.openTime,
205→      startTime: drizzleEvent.startTime,
206→      pricing: (drizzleEvent.pricing as PricingTier[]) ?? null,
207→      performers: (drizzleEvent.performers as Performer[]) ?? null,
208→      hashtags: drizzleEvent.hashtags ?? null,
209→    };
210→  }
211→}
