70→/**
71→ * グリッドアイテムのボーダースタイルを計算
72→ * NOTE: ピックアップイベントは最大4件の前提で実装（@see PICKUP_EVENTS_LIMIT）
73→ */
74→const getBorderClassName = (index: number) => {
75→  // 2列レイアウト（デフォルト〜lg未満）
76→  const needsRightBorder2Col = index % 2 === 0;
77→  const needsBottomBorder2Col = index < 2;
78→
79→  // 4列レイアウト（lg以上）: 4件=1行なので bottom border 不要
80→  const needsRightBorder4Col = index % 4 < 3;
81→
82→  // 全アイテムにborder-r/border-bを付けてコンテンツ領域を揃え、
83→  // 不要な箇所はtransparentで非表示にする
84→  return cn(
85→    "border-r border-b",
86→    needsRightBorder2Col ? "border-r-soypoy-secondary" : "border-r-transparent",
87→    needsBottomBorder2Col
88→      ? "border-b-soypoy-secondary"
89→      : "border-b-transparent",
90→    // 4列: border-b不要、border-rは最後以外に表示
91→    "lg:border-b-0",
92→    needsRightBorder4Col
93→      ? "lg:border-r-soypoy-secondary"
94→      : "lg:border-r-transparent",
95→  );
96→};
